# @kern:requires x >= 0
# @kern:ensures result >= 0
def clamp(x):
    if x > 0:
        return x
    return x - 1

# @kern:requires balance >= 0 and amount >= 0
# @kern:ensures result >= 0
def debit(balance, amount):
    if amount > 1000:
        return balance
    return balance - amount

# @kern:requires balance >= 0 and amount >= 0
# @kern:ensures result <= 1000
def topup(balance, amount):
    if balance + amount > 1000:
        return 1000
    return balance + amount

# @kern:ensures result >= 0
def twice(x):
    return x + x
